import hashlib
import hmac


def verify(password: str, stored: str) -> bool:
    salt, digest = stored.split("$", 1)
    attempt = hashlib.scrypt(password.encode(), salt=bytes.fromhex(salt), n=2**14, r=8, p=1).hex()
    return hmac.compare_digest(attempt, digest)

