from fastapi import APIRouter, Depends, HTTPException
from pydantic import BaseModel

from app.audit import record
from app.auth import serializer
from app.db import get_db
from app.passwords import verify

router = APIRouter(prefix="/sessions", tags=["sessions"])


class Credentials(BaseModel):
    email: str
    password: str


@router.post("", status_code=201)
def sign_in(credentials: Credentials, db=Depends(get_db)):
    customer = db.execute(
        "SELECT id, password_hash FROM customers WHERE email = %s", (credentials.email,)
    ).fetchone()
    if customer is None or not verify(credentials.password, customer["password_hash"]):
        raise HTTPException(status_code=401, detail="Wrong email or password")
    token = serializer.dumps(customer["id"])
    record("sign-in", customer=customer["id"], token=token)
    return {"token": token}
